package com.bank.dispute.service;

import java.util.logging.Logger;

// Decides whether a subset of charges sums exactly to a disputed target.
public class DisputeCheckService {
    private static final Logger log = Logger.getLogger(DisputeCheckService.class.getName());

    public boolean hasSubsetSum(int[] charges, int target) {
        if (target < 0) return false;
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;                               // empty subset reaches 0
        for (int c : charges) {
            for (int t = target; t >= c; t--) {     // high → low ⇒ each charge once
                dp[t] = dp[t] || dp[t - c];
            }
            if (dp[target]) break;                  // early exit on success
        }
        final boolean ans = dp[target];
        log.info(() -> "Exact subset for target " + target + " = " + ans);
        return dp[target];
    }
}
