package com.bank.dispute;

import com.bank.dispute.service.DisputeCheckService;
import java.util.logging.Logger;

public class DisputeCheckApplication {
    private static final Logger log = Logger.getLogger(DisputeCheckApplication.class.getName());

    public static void main(String[] args) {
        DisputeCheckService service = new DisputeCheckService();
        int[] charges = {120, 75, 200, 45};     // individual charges (rupees)
        int disputed = 165;                      // claimed disputed total
        boolean reachable = service.hasSubsetSum(charges, disputed);
        log.info("Can charges sum exactly to Rs." + disputed + "? " + reachable);
    }
}
